147	                ...ir,
148	                modo: 'tipoValor' as const,
149	                tipoValor: ir.tipoValor ?? 'Porcentagem',
150	            },
151	        };
152	    });
153	
154	    return changed ? { ...scenario, outputs } : scenario;
