250	export function normalizeIrOutput(value: unknown): IrOutputValue {
251	    if (!value || typeof value !== 'object') return emptyIR();
252	    const raw = value as IrOutputValue;
253	    const ativo = Boolean(raw.ativo);
254	    const numeroMeses = raw.numeroMeses ?? '';
255	    const effectiveModo =
256	        raw.modo === 'rra' || raw.modo === 'tipoValor'
257	            ? raw.modo
258	            : ativo
259	              ? 'tipoValor'
260	              : null;
261	    const definirNumeroMeses =
262	        raw.definirNumeroMeses !== undefined
263	            ? Boolean(raw.definirNumeroMeses)
264	            : effectiveModo === 'rra' && String(numeroMeses).trim() !== '';
265	
266	    return {
267	        ativo,
268	        modo: effectiveModo,
269	        tipoValor: raw.tipoValor ?? 'Porcentagem',
270	        aliquota: (typeof raw.aliquota === 'string' && raw.aliquota.trim()) || '3%',
271	        baseCalculo: raw.baseCalculo ?? 'Principal',
272	        deducContrib: raw.deducContrib ?? 'Não',
273	        deducHonor: raw.deducHonor ?? 'Sim',
274	        definirNumeroMeses,
275	        numeroMeses,
276	    };
