310	export function importConfig(json: unknown): TriggerScenario[] {
311	    const data = typeof json === 'string' ? JSON.parse(json) : json;
312	    if (!data || typeof data !== 'object') return [];
313	    const parsed = data as { version?: number; scenarios?: TriggerScenario[] };
314	    if (parsed.version !== SCHEMA_VERSION) {
315	        console.warn(`Versão de schema ${parsed.version} != atual ${SCHEMA_VERSION}.`);
316	    }
317	    return (parsed.scenarios || []).map((scenario) => ({
318	        ...scenario,
319	        conditions: (scenario.conditions || []).map((condition) => ({
320	            ...condition,
321	            value: coerceConditionValue(condition.field, condition.value),
322	        })),
323	        outputs: (scenario.outputs || []).map((output) =>
324	            output.field === 'outrasDeducoes'
325	                ? { ...output, value: normalizeDeducoesOutput(output.value) }
326	                : output.field === 'incideIR'
327	                  ? { ...output, value: normalizeIrOutput(output.value) }
328	                  : output.field === 'contribuicaoPrevidenciaria'
329	                    ? { ...output, value: normalizeContribuicaoOutput(output.value) }
330	                    : output,
331	        ),
332	    }));
333	}
