335	export function validateScenario(scenario: TriggerScenario): string[] {
336	    const errors: string[] = [];
337	    if (!scenario.conditions?.length) errors.push('Cenário sem condições.');
338	    if (!scenario.outputs?.length) errors.push('Cenário sem outputs.');
339	
340	    scenario.conditions?.forEach((condition, index) => {
341	        const cfg = CONDITION_FIELDS[condition.field];
342	        if (!cfg) errors.push(`Condição ${index + 1}: campo inválido.`);
343	        else if (isConditionValueEmpty(condition.field, condition.value)) {
344	            errors.push(`Condição ${index + 1} (${cfg.label}): valor vazio.`);
345	        }
346	    });
347	
348	    scenario.outputs?.forEach((output, index) => {
349	        const cfg = OUTPUT_FIELDS[output.field];
350	        if (!cfg) {
351	            errors.push(`Output ${index + 1}: campo inválido.`);
352	            return;
353	        }
354	        const value = output.value;
355	        if (cfg.type === 'ir' && (value as IrOutputValue).ativo) {
356	            const ir = normalizeIrOutput(value);
357	            if (
358	                ir.modo === 'rra' &&
359	                scenarioHasTributariaNaturezaCondition(scenario)
360	            ) {
361	                errors.push(
362	                    `Output ${index + 1} (IR): RRA não se aplica a natureza Tributária.`,
363	                );
364	            }
365	            if (ir.modo === 'tipoValor' && !ALIQUOTAS_IR.includes(ir.aliquota as (typeof ALIQUOTAS_IR)[number])) {
366	                errors.push(`Output ${index + 1} (IR): alíquota deve ser 1,5% ou 3%.`);
367	            }
368	            if (ir.modo === 'rra' && ir.definirNumeroMeses) {
369	                const months = Number(ir.numeroMeses);
370	                if (!Number.isInteger(months) || months < 1) {
371	                    errors.push(`Output ${index + 1} (IR/RRA): número de meses deve ser inteiro ≥ 1.`);
372	                }
373	            }
374	        }
375	        if (cfg.type === 'deducoes' && (value as DeducoesOutputValue).ativo) {
376	            const ded = value as DeducoesOutputValue;
377	            if (!ded.deducoes?.length) {
378	                errors.push(`Output ${index + 1} (Deduções): adicione ao menos uma dedução.`);
379	            }
380	            ded.deducoes?.forEach((item, dedIndex) => {
381	                if (!item.tipo || item.tipo === 'selecione') {
382	                    errors.push(`Output ${index + 1} (Deduções ${dedIndex + 1}): categoria obrigatória.`);
383	                }
384	                const amount = Number(String(item.valor).replace(',', '.'));
385	                if (Number.isNaN(amount) || amount < 0) {
386	                    errors.push(`Output ${index + 1} (Deduções ${dedIndex + 1}): valor inválido.`);
387	                }
388	            });
389	        }
390	        if (cfg.type === 'contribuicao' && (value as ContribuicaoPrevidenciariaOutputValue).ativo) {
391	            const contrib = normalizeContribuicaoOutput(value);
392	            if (!String(contrib.valor ?? '').trim()) {
393	                errors.push(`Output ${index + 1} (Contribuição): valor obrigatório.`);
394	            }
395	        }
396	    });
397	
398	    return errors;
399	}
