401	function conditionFingerprint(condition: TriggerCondition): string {
402	    return `${condition.field}|${condition.operator}|${normalizeConditionValueForFingerprint(condition.field, condition.value)}`;
403	}
404	
405	function outputFingerprint(output: TriggerOutput): string {
406	    if (output.field === 'incideIR') {
407	        const ir = normalizeIrOutput(output.value);
408	        return `incideIR|${JSON.stringify({
409	            ativo: ir.ativo,
410	            modo: ir.ativo ? (ir.modo ?? 'tipoValor') : ir.modo,
411	            tipoValor: ir.tipoValor,
412	            aliquota: ir.aliquota,
413	            baseCalculo: ir.baseCalculo,
414	            deducContrib: ir.deducContrib,
415	            deducHonor: ir.deducHonor,
416	            definirNumeroMeses: ir.definirNumeroMeses,
417	            numeroMeses: String(ir.numeroMeses ?? ''),
418	        })}`;
419	    }
420	    if (output.field === 'outrasDeducoes') {
421	        const ded = normalizeDeducoesOutput(output.value);
422	        return `outrasDeducoes|${JSON.stringify(ded)}`;
423	    }
424	    if (output.field === 'contribuicaoPrevidenciaria') {
425	        const contrib = normalizeContribuicaoOutput(output.value);
426	        return `contribuicaoPrevidenciaria|${JSON.stringify(contrib)}`;
427	    }
428	    return `${output.field}|${JSON.stringify(output.value ?? {})}`;
429	}
430	
431	/** Fingerprint of logic + conditions only (outputs ignored). */
432	export function scenarioConditionsFingerprint(scenario: TriggerScenario): string {
433	    const logic = (scenario.logic ?? 'AND').toUpperCase();
434	    const conditions = [...(scenario.conditions ?? [])].map(conditionFingerprint).sort().join(';');
435	    return `${logic}::${conditions}`;
436	}
437	
438	/** Full fingerprint including outputs (for exact clone detection). */
439	export function scenarioFingerprint(scenario: TriggerScenario): string {
440	    const conditionsKey = scenarioConditionsFingerprint(scenario);
441	    const outputs = [...(scenario.outputs ?? [])].map(outputFingerprint).sort().join(';');
442	    return `${conditionsKey}::${outputs}`;
443	}
444	
445	export function findDuplicateScenarioGroups(scenarios: TriggerScenario[]): string[][] {
446	    const byFingerprint = new Map<string, string[]>();
447	
448	    scenarios.forEach((scenario) => {
449	        const fingerprint = scenarioConditionsFingerprint(scenario);
450	        const label = scenario.name?.trim() || scenario.id;
451	        const group = byFingerprint.get(fingerprint) ?? [];
452	        group.push(label);
453	        byFingerprint.set(fingerprint, group);
454	    });
455	
456	    return Array.from(byFingerprint.values()).filter((group) => group.length > 1);
457	}
458	
459	export function validateConfig(config: { version: number; scenarios: TriggerScenario[] }): string[] {
460	    const errors: string[] = [];
461	    if (config.version !== SCHEMA_VERSION) {
462	        errors.push(`Versão de schema inválida: ${config.version}.`);
463	    }
464	    config.scenarios.forEach((scenario) => {
465	        validateScenario(scenario).forEach((err) => errors.push(`${scenario.name}: ${err}`));
466	    });
467	
468	    findDuplicateScenarioGroups(config.scenarios).forEach((group) => {
469	        errors.push(
470	            `Condições duplicadas (${group.join(' × ')}): dois cenários não podem ter o mesmo SE.`,
471	        );
472	    });
473	
474	    // Potential output conflicts are surfaced in CalculatorTriggersConflictsPanel
475	    // and must not hard-block save (authors fix pairs iteratively). Runtime still
476	    // skips applying when conflicts fire on an oficio.
477	    return errors;
478	}
