import {
    coerceConditionValue,
    conditionValuesInclude,
    isConditionValueEmpty,
    normalizeConditionValueForFingerprint,
} from '@/functions/calculator-triggers/condition-value';
import { PERSON_TYPE_OPTIONS } from '@/functions/calculator-triggers/person-type';
import {
    CALC_CLASSE_CREDITO_OPTIONS,
    CALC_NATUREZA_OPTIONS,
} from '@/components/calculadora/calculadora-form-options';
import type {
    ConditionFieldKey,
    ContribuicaoPrevidenciariaOutputValue,
    DeducoesOutputValue,
    IrOutputValue,
    OutputFieldKey,
    TriggerCondition,
    TriggerDeducaoItem,
    TriggerOutput,
    TriggerScenario,
} from '@/types/calculator-triggers';

export const SCHEMA_VERSION = 1;

export const CONDITION_FIELDS: Record<
    ConditionFieldKey,
    {
        label: string;
        type: 'select' | 'text' | 'date' | 'boolean';
        options?: string[];
        placeholder?: string;
        /** Permite múltiplos valores (ex.: tribunal via combobox). */
        multiselect?: boolean;
    }
> = {
    tipo: {
        label: 'Tipo',
        type: 'select',
        options: ['PRECATÓRIO', 'RPV', 'CRÉDITO JUDICIAL'],
    },
    natureza: {
        label: 'Natureza',
        type: 'select',
        options: CALC_NATUREZA_OPTIONS.map((option) => option.label),
    },
    esfera: {
        label: 'Esfera',
        type: 'select',
        options: ['Federal', 'Estadual', 'Municipal'],
    },
    tribunal: {
        label: 'Tribunal',
        type: 'text',
        multiselect: true,
    },
    enteDevedor: { label: 'Ente Devedor', type: 'text', placeholder: 'Ex.: UNIÃO FEDERAL' },
    dataRequisicao: { label: 'Data de Requisição / Recebimento', type: 'date' },
    destacamentoHonorarios: {
        label: 'Já possui destacamento de honorários',
        type: 'boolean',
    },
    cpfCnpj: {
        label: 'CPF/CNPJ',
        type: 'select',
        options: [...PERSON_TYPE_OPTIONS],
    },
    especie: {
        label: 'Espécie',
        type: 'select',
        options: ['Principal', 'Honorários', 'Sucumbência'],
    },
    juizoVara: { label: 'Juízo/Vara', type: 'text', placeholder: 'Ex.: 1ª Vara da Fazenda Pública' },
    classeCredito: {
        label: 'Classe do Crédito',
        type: 'select',
        options: CALC_CLASSE_CREDITO_OPTIONS.map((option) => option.label),
    },
};

export const OPERATORS = {
    select: [
        { value: 'eq', label: 'é igual a' },
        { value: 'neq', label: 'é diferente de' },
    ],
    text: [
        { value: 'eq', label: 'é igual a' },
        { value: 'neq', label: 'é diferente de' },
        { value: 'contains', label: 'contém' },
        { value: 'startsWith', label: 'começa com' },
    ],
    date: [
        { value: 'eq', label: 'é igual a' },
        { value: 'before', label: 'é anterior a' },
        { value: 'after', label: 'é posterior a' },
    ],
    boolean: [{ value: 'is', label: 'é' }],
} as const;

export const OUTPUT_FIELDS: Record<
    OutputFieldKey,
    { label: string; type: 'deducoes' | 'ir' | 'contribuicao'; group: string }
> = {
    outrasDeducoes: { label: 'Há outras deduções?', type: 'deducoes', group: 'Deduções' },
    incideIR: { label: 'Incidência de IR', type: 'ir', group: 'Imposto de Renda' },
    contribuicaoPrevidenciaria: {
        label: 'Contribuição previdenciária',
        type: 'contribuicao',
        group: 'Contribuição',
    },
};

export const ALIQUOTAS_IR = ['1,5%', '3%'] as const;
export const BASES_RRA = ['Principal', 'Principal selicado', 'Valor bruto'] as const;

export function isTributariaNatureza(value: unknown): boolean {
    const text = String(value ?? '')
        .trim()
        .toUpperCase()
        .replace(/Á/g, 'A')
        .replace(/Ã/g, 'A');
    return text === 'TRIBUTARIA';
}

export function scenarioHasTributariaNaturezaCondition(scenario: TriggerScenario): boolean {
    return (scenario.conditions ?? []).some(
        (condition) =>
            condition.field === 'natureza' &&
            condition.operator === 'eq' &&
            conditionValuesInclude(condition.value, (value) => isTributariaNatureza(value)),
    );
}

/** IR/RRA does not apply to tax-related nature; coerce outputs when scenario targets Tributária. */
export function normalizeScenarioIrForTributaria(scenario: TriggerScenario): TriggerScenario {
    if (!scenarioHasTributariaNaturezaCondition(scenario)) return scenario;

    let changed = false;
    const outputs = (scenario.outputs ?? []).map((output) => {
        if (output.field !== 'incideIR') return output;
        const ir = normalizeIrOutput(output.value);
        if (ir.modo !== 'rra') return output;
        changed = true;
        return {
            ...output,
            value: {
                ...ir,
                modo: 'tipoValor' as const,
                tipoValor: ir.tipoValor ?? 'Porcentagem',
            },
        };
    });

    return changed ? { ...scenario, outputs } : scenario;
}

export function normalizeDeducoesOutput(value: unknown): DeducoesOutputValue {
    if (!value || typeof value !== 'object') return emptyDeducoes();
    const raw = value as Record<string, unknown>;
    if (Array.isArray(raw.deducoes)) {
        return {
            ativo: true,
            deducoes: raw.deducoes.map((item) => {
                const row = item as Record<string, unknown>;
                return {
                    tipo: String(row.tipo ?? ''),
                    tipo_valor: String(row.tipo_valor ?? 'PERCENTUAL'),
                    valor: String(row.valor ?? ''),
                    base_calculo_deducao: String(row.base_calculo_deducao ?? 'BRUTO'),
                    efeito_juros: (row.efeito_juros as TriggerDeducaoItem['efeito_juros']) ?? 'nenhum',
                    deduz_base_ir: Boolean(row.deduz_base_ir),
                };
            }),
        };
    }
    if ('percentual' in raw) {
        const ativo = Boolean(raw.ativo);
        return {
            ativo,
            deducoes: ativo
                ? [
                      {
                          tipo: 'outros_descontos',
                          tipo_valor: 'PERCENTUAL',
                          valor: String(raw.percentual ?? ''),
                          base_calculo_deducao: 'BRUTO',
                          efeito_juros: 'nenhum',
                          deduz_base_ir: false,
                      },
                  ]
                : [],
        };
    }
    return emptyDeducoes();
}

export function emptyDeducaoItem(): TriggerDeducaoItem {
    return {
        tipo: '',
        tipo_valor: 'PERCENTUAL',
        valor: '',
        base_calculo_deducao: 'BRUTO',
        efeito_juros: 'nenhum',
        deduz_base_ir: false,
    };
}

export function emptyContribuicao(): ContribuicaoPrevidenciariaOutputValue {
    return {
        ativo: true,
        tipoValor: 'PERCENTUAL',
        valor: '',
        baseCalculo: 'PRINCIPAL',
    };
}

export function normalizeContribuicaoOutput(value: unknown): ContribuicaoPrevidenciariaOutputValue {
    if (!value || typeof value !== 'object') return emptyContribuicao();
    const raw = value as ContribuicaoPrevidenciariaOutputValue;
    return {
        ativo: Boolean(raw.ativo),
        tipoValor: String(raw.tipoValor || 'PERCENTUAL'),
        valor: String(raw.valor ?? ''),
        baseCalculo: String(raw.baseCalculo || 'PRINCIPAL'),
    };
}

export function emptyDeducoes(): DeducoesOutputValue {
    return { ativo: true, deducoes: [] };
}

export function uid(): string {
    return Math.random().toString(36).slice(2, 9);
}

export function emptyIR(): IrOutputValue {
    return {
        ativo: false,
        modo: 'tipoValor',
        tipoValor: 'Porcentagem',
        aliquota: '3%',
        baseCalculo: 'Principal',
        deducContrib: 'Não',
        deducHonor: 'Sim',
        definirNumeroMeses: false,
        numeroMeses: '',
    };
}

export function normalizeIrOutput(value: unknown): IrOutputValue {
    if (!value || typeof value !== 'object') return emptyIR();
    const raw = value as IrOutputValue;
    const ativo = Boolean(raw.ativo);
    const numeroMeses = raw.numeroMeses ?? '';
    const effectiveModo =
        raw.modo === 'rra' || raw.modo === 'tipoValor'
            ? raw.modo
            : ativo
              ? 'tipoValor'
              : null;
    const definirNumeroMeses =
        raw.definirNumeroMeses !== undefined
            ? Boolean(raw.definirNumeroMeses)
            : effectiveModo === 'rra' && String(numeroMeses).trim() !== '';

    return {
        ativo,
        modo: effectiveModo,
        tipoValor: raw.tipoValor ?? 'Porcentagem',
        aliquota: (typeof raw.aliquota === 'string' && raw.aliquota.trim()) || '3%',
        baseCalculo: raw.baseCalculo ?? 'Principal',
        deducContrib: raw.deducContrib ?? 'Não',
        deducHonor: raw.deducHonor ?? 'Sim',
        definirNumeroMeses,
        numeroMeses,
    };
}

export function outputInitialValue(
    field: OutputFieldKey,
): DeducoesOutputValue | IrOutputValue | ContribuicaoPrevidenciariaOutputValue {
    const type = OUTPUT_FIELDS[field]?.type;
    if (type === 'ir') return emptyIR();
    if (type === 'contribuicao') return emptyContribuicao();
    return emptyDeducoes();
}

export function newCondition(): TriggerCondition {
    return { id: uid(), field: 'tipo', operator: 'eq', value: '' };
}

export function newOutput(): TriggerOutput {
    return { id: uid(), field: 'outrasDeducoes', value: emptyDeducoes() };
}

export function newScenario(index: number): TriggerScenario {
    return {
        id: uid(),
        name: `Cenário ${index}`,
        logic: 'AND',
        conditions: [newCondition()],
        outputs: [newOutput()],
    };
}

export function exportConfig(scenarios: TriggerScenario[]) {
    return { version: SCHEMA_VERSION, scenarios };
}

export function importConfig(json: unknown): TriggerScenario[] {
    const data = typeof json === 'string' ? JSON.parse(json) : json;
    if (!data || typeof data !== 'object') return [];
    const parsed = data as { version?: number; scenarios?: TriggerScenario[] };
    if (parsed.version !== SCHEMA_VERSION) {
        console.warn(`Versão de schema ${parsed.version} != atual ${SCHEMA_VERSION}.`);
    }
    return (parsed.scenarios || []).map((scenario) => ({
        ...scenario,
        conditions: (scenario.conditions || []).map((condition) => ({
            ...condition,
            value: coerceConditionValue(condition.field, condition.value),
        })),
        outputs: (scenario.outputs || []).map((output) =>
            output.field === 'outrasDeducoes'
                ? { ...output, value: normalizeDeducoesOutput(output.value) }
                : output.field === 'incideIR'
                  ? { ...output, value: normalizeIrOutput(output.value) }
                  : output.field === 'contribuicaoPrevidenciaria'
                    ? { ...output, value: normalizeContribuicaoOutput(output.value) }
                    : output,
        ),
    }));
}

export function validateScenario(scenario: TriggerScenario): string[] {
    const errors: string[] = [];
    if (!scenario.conditions?.length) errors.push('Cenário sem condições.');
    if (!scenario.outputs?.length) errors.push('Cenário sem outputs.');

    scenario.conditions?.forEach((condition, index) => {
        const cfg = CONDITION_FIELDS[condition.field];
        if (!cfg) errors.push(`Condição ${index + 1}: campo inválido.`);
        else if (isConditionValueEmpty(condition.field, condition.value)) {
            errors.push(`Condição ${index + 1} (${cfg.label}): valor vazio.`);
        }
    });

    scenario.outputs?.forEach((output, index) => {
        const cfg = OUTPUT_FIELDS[output.field];
        if (!cfg) {
            errors.push(`Output ${index + 1}: campo inválido.`);
            return;
        }
        const value = output.value;
        if (cfg.type === 'ir' && (value as IrOutputValue).ativo) {
            const ir = normalizeIrOutput(value);
            if (
                ir.modo === 'rra' &&
                scenarioHasTributariaNaturezaCondition(scenario)
            ) {
                errors.push(
                    `Output ${index + 1} (IR): RRA não se aplica a natureza Tributária.`,
                );
            }
            if (ir.modo === 'tipoValor' && !ALIQUOTAS_IR.includes(ir.aliquota as (typeof ALIQUOTAS_IR)[number])) {
                errors.push(`Output ${index + 1} (IR): alíquota deve ser 1,5% ou 3%.`);
            }
            if (ir.modo === 'rra' && ir.definirNumeroMeses) {
                const months = Number(ir.numeroMeses);
                if (!Number.isInteger(months) || months < 1) {
                    errors.push(`Output ${index + 1} (IR/RRA): número de meses deve ser inteiro ≥ 1.`);
                }
            }
        }
        if (cfg.type === 'deducoes' && (value as DeducoesOutputValue).ativo) {
            const ded = value as DeducoesOutputValue;
            if (!ded.deducoes?.length) {
                errors.push(`Output ${index + 1} (Deduções): adicione ao menos uma dedução.`);
            }
            ded.deducoes?.forEach((item, dedIndex) => {
                if (!item.tipo || item.tipo === 'selecione') {
                    errors.push(`Output ${index + 1} (Deduções ${dedIndex + 1}): categoria obrigatória.`);
                }
                const amount = Number(String(item.valor).replace(',', '.'));
                if (Number.isNaN(amount) || amount < 0) {
                    errors.push(`Output ${index + 1} (Deduções ${dedIndex + 1}): valor inválido.`);
                }
            });
        }
        if (cfg.type === 'contribuicao' && (value as ContribuicaoPrevidenciariaOutputValue).ativo) {
            const contrib = normalizeContribuicaoOutput(value);
            if (!String(contrib.valor ?? '').trim()) {
                errors.push(`Output ${index + 1} (Contribuição): valor obrigatório.`);
            }
        }
    });

    return errors;
}

function conditionFingerprint(condition: TriggerCondition): string {
    return `${condition.field}|${condition.operator}|${normalizeConditionValueForFingerprint(condition.field, condition.value)}`;
}

function outputFingerprint(output: TriggerOutput): string {
    if (output.field === 'incideIR') {
        const ir = normalizeIrOutput(output.value);
        return `incideIR|${JSON.stringify({
            ativo: ir.ativo,
            modo: ir.ativo ? (ir.modo ?? 'tipoValor') : ir.modo,
            tipoValor: ir.tipoValor,
            aliquota: ir.aliquota,
            baseCalculo: ir.baseCalculo,
            deducContrib: ir.deducContrib,
            deducHonor: ir.deducHonor,
            definirNumeroMeses: ir.definirNumeroMeses,
            numeroMeses: String(ir.numeroMeses ?? ''),
        })}`;
    }
    if (output.field === 'outrasDeducoes') {
        const ded = normalizeDeducoesOutput(output.value);
        return `outrasDeducoes|${JSON.stringify(ded)}`;
    }
    if (output.field === 'contribuicaoPrevidenciaria') {
        const contrib = normalizeContribuicaoOutput(output.value);
        return `contribuicaoPrevidenciaria|${JSON.stringify(contrib)}`;
    }
    return `${output.field}|${JSON.stringify(output.value ?? {})}`;
}

/** Fingerprint of logic + conditions only (outputs ignored). */
export function scenarioConditionsFingerprint(scenario: TriggerScenario): string {
    const logic = (scenario.logic ?? 'AND').toUpperCase();
    const conditions = [...(scenario.conditions ?? [])].map(conditionFingerprint).sort().join(';');
    return `${logic}::${conditions}`;
}

/** Full fingerprint including outputs (for exact clone detection). */
export function scenarioFingerprint(scenario: TriggerScenario): string {
    const conditionsKey = scenarioConditionsFingerprint(scenario);
    const outputs = [...(scenario.outputs ?? [])].map(outputFingerprint).sort().join(';');
    return `${conditionsKey}::${outputs}`;
}

export function findDuplicateScenarioGroups(scenarios: TriggerScenario[]): string[][] {
    const byFingerprint = new Map<string, string[]>();

    scenarios.forEach((scenario) => {
        const fingerprint = scenarioConditionsFingerprint(scenario);
        const label = scenario.name?.trim() || scenario.id;
        const group = byFingerprint.get(fingerprint) ?? [];
        group.push(label);
        byFingerprint.set(fingerprint, group);
    });

    return Array.from(byFingerprint.values()).filter((group) => group.length > 1);
}

export function validateConfig(config: { version: number; scenarios: TriggerScenario[] }): string[] {
    const errors: string[] = [];
    if (config.version !== SCHEMA_VERSION) {
        errors.push(`Versão de schema inválida: ${config.version}.`);
    }
    config.scenarios.forEach((scenario) => {
        validateScenario(scenario).forEach((err) => errors.push(`${scenario.name}: ${err}`));
    });

    findDuplicateScenarioGroups(config.scenarios).forEach((group) => {
        errors.push(
            `Condições duplicadas (${group.join(' × ')}): dois cenários não podem ter o mesmo SE.`,
        );
    });

    // Potential output conflicts are surfaced in CalculatorTriggersConflictsPanel
    // and must not hard-block save (authors fix pairs iteratively). Runtime still
    // skips applying when conflicts fire on an oficio.
    return errors;
}

